mapper.select:
select room_id roomId,room_code roomCode,room_name roomName
from live_room
where lower(trim(regexp_replace(room_name,'[[:space:]]+',' ')))=#{roomNameKey}
   or lower(trim(regexp_replace(live_account,'[[:space:]]+',' ')))=#{roomNameKey}
order by room_id limit 1

select /*+ MAX_EXECUTION_TIME(5000) */ c.id customerId,c.display_name nickname, case when c.consult_stage='NOT_CONSULTED' and exists(select 1 from dy_audience_v2_manual_registration sr where sr.customer_id=c.id) then 'CONTACTED' else c.consult_stage end stage, c.interaction_status interactionStatus,c.fan_status fanStatus,c.owner_user_id ownerUserId,coalesce(nullif(ou.nick_name,''),c.owner_name) ownerName, page.sessionId,page.lastInteractionAt,page.interactionCount,page.commentCount,page.interactionType, (select ce.content from dy_audience_v2_interaction_event ce where ce.customer_id=c.id and ce.event_type='COMMENT' and ce.session_id=#{sessionId} and ce.occurred_at>=concat(#{beginDate},' 00:00:00') and ce.occurred_at<date_add(#{endDate},interval 1 day) order by ce.occurred_at desc,ce.id desc limit 1) lastComment, (select count(distinct vp.session_id) from dy_audience_v2_viewer_presence vp where vp.customer_id=c.id and vp.session_id=#{sessionId}and vp.first_seen_at>=concat(#{beginDate},' 00:00:00')and vp.first_seen_at<date_add(#{endDate},interval 1 day)) visitCount, (select coalesce(sum(least(greatest(timestampdiff(second,vp.first_seen_at,vp.last_seen_at),0),greatest(vp.seen_count,0)*300,21600)),0) from dy_audience_v2_viewer_presence vp where vp.customer_id=c.id and vp.session_id=#{sessionId}and vp.first_seen_at>=concat(#{beginDate},' 00:00:00')and vp.first_seen_at<date_add(#{endDate},interval 1 day)) watchSeconds, s.room_name roomName,s.live_date liveDate, (select o.id from dy_audience_v2_opportunity o where o.customer_id=c.id and o.session_id=#{sessionId} order by o.id desc limit 1) opportunityId, (select o.anchor_user_id from dy_audience_v2_opportunity o where o.customer_id=c.id and o.session_id=#{sessionId} order by o.id desc limit 1) anchorUserId, (select coalesce(nullif(au.nick_name,''),nullif(o.anchor_name,'')) from dy_audience_v2_opportunity o left join sys_user au on au.user_id=o.anchor_user_id where o.customer_id=c.id and o.session_id=#{sessionId} order by o.id desc limit 1) anchorName, (select o.controller_user_id from dy_audience_v2_opportunity o where o.customer_id=c.id and o.session_id=#{sessionId} order by o.id desc limit 1) controllerUserId, (select coalesce(nullif(cu.nick_name,''),nullif(o.controller_name,'')) from dy_audience_v2_opportunity o left join sys_user cu on cu.user_id=o.controller_user_id where o.customer_id=c.id and o.session_id=#{sessionId} order by o.id desc limit 1) controllerName, (select o.special_mark from dy_audience_v2_opportunity o where o.customer_id=c.id and o.session_id=#{sessionId} order by o.id desc limit 1) specialMark, (select ft.id from dy_audience_v2_followup_task ft join dy_audience_v2_opportunity fo on fo.id=ft.opportunity_id where fo.customer_id=c.id and ft.status not in ('DONE','RELEASED') and fo.session_id=#{sessionId} order by (ft.task_date<cast(convert_tz(now(),'+00:00','+08:00') as date)) desc,ft.task_date,ft.id desc limit 1) taskId, (select case when ft.status='PENDING' and ft.task_date<cast(convert_tz(now(),'+00:00','+08:00') as date) then 'OVERDUE' else ft.status end from dy_audience_v2_followup_task ft join dy_audience_v2_opportunity fo on fo.id=ft.opportunity_id where fo.customer_id=c.id and ft.status not in ('DONE','RELEASED') and fo.session_id=#{sessionId} order by (ft.task_date<cast(convert_tz(now(),'+00:00','+08:00') as date)) desc,ft.task_date,ft.id desc limit 1) taskStatus, (select ft.task_type from dy_audience_v2_followup_task ft join dy_audience_v2_opportunity fo on fo.id=ft.opportunity_id where fo.customer_id=c.id and ft.status not in ('DONE','RELEASED') and fo.session_id=#{sessionId} order by (ft.task_date<current_date) desc,ft.task_date,ft.id desc limit 1) taskType, (select ft.task_date from dy_audience_v2_followup_task ft join dy_audience_v2_opportunity fo on fo.id=ft.opportunity_id where fo.customer_id=c.id and ft.status not in ('DONE','RELEASED') and fo.session_id=#{sessionId} order by (ft.task_date<current_date) desc,ft.task_date,ft.id desc limit 1) taskDate, (select ft.assignee_user_id from dy_audience_v2_followup_task ft join dy_audience_v2_opportunity fo on fo.id=ft.opportunity_id where fo.customer_id=c.id and ft.status not in ('DONE','RELEASED') and fo.session_id=#{sessionId} order by (ft.task_date<current_date) desc,ft.task_date,ft.id desc limit 1) taskAssigneeUserId, (select ft.assignee_name from dy_audience_v2_followup_task ft join dy_audience_v2_opportunity fo on fo.id=ft.opportunity_id where fo.customer_id=c.id and ft.status not in ('DONE','RELEASED') and fo.session_id=#{sessionId} order by (ft.task_date<current_date) desc,ft.task_date,ft.id desc limit 1) taskAssigneeName, (select ol.order_no from dy_audience_v2_order_link ol join dy_audience_v2_opportunity oo on oo.id=ol.opportunity_id where ol.customer_id=c.id and oo.session_id=#{sessionId} order by ol.id desc limit 1) orderNo, (select ol.order_status from dy_audience_v2_order_link ol join dy_audience_v2_opportunity oo on oo.id=ol.opportunity_id where ol.customer_id=c.id and oo.session_id=#{sessionId} order by ol.id desc limit 1) orderStatus, case when exists(select 1 from dy_audience_v2_identity si where si.customer_id=c.id and si.same_name_multi_identity=1) then 1 else 0 end sameNameMultiIdentity, page.sourceType, case when exists(select 1 from dy_audience_v2_followup_task itask join dy_audience_v2_opportunity ao on ao.id=itask.opportunity_id where ao.customer_id=c.id and itask.task_type='PHONE_SERVICE' and itask.status not in ('DONE','RELEASED')) then 'VIEW_HANDOFF' when exists(select 1 from dy_audience_v2_followup_task itask join dy_audience_v2_opportunity ao on ao.id=itask.opportunity_id where ao.customer_id=c.id and itask.status not in ('DONE','RELEASED')) then 'CONTINUE' when not exists(select 1 from dy_audience_v2_manual_registration ar where ar.customer_id=c.id and ar.session_id=#{sessionId}) then 'REGISTER' else 'VIEW' end primaryAction from (
select aggregate.customerId,aggregate.sessionId,aggregate.lastInteractionAt, aggregate.interactionCount,aggregate.commentCount,aggregate.interactionType,aggregate.sourceType from () aggregate join dy_audience_v2_customer c on c.id=aggregate.customerId
order by aggregate.lastInteractionAt desc,aggregate.customerId desc limit #{offset},#{limit}
select candidate.customerId, cast(substring_index(group_concat(e.session_id order by e.occurred_at desc,e.id desc),',',1) as unsigned) sessionId, max(e.occurred_at) lastInteractionAt,count(e.id) interactionCount, sum(case when e.event_type='COMMENT' then 1 else 0 end) commentCount, 'COMMENT' interactionType, case when sum(case when e.source_type='PLUGIN_REALTIME' then 1 else 0 end)>0 then 'PLUGIN' else 'MANUAL' end sourceType from ( select c.id customerId from dy_audience_v2_interaction_event ce force index (idx_av2_event_type_time_customer) join dy_audience_v2_customer c on c.id=ce.customer_id
group by c.id order by max(ce.occurred_at) desc,c.id desc limit #{offset},#{limit} ) candidate join dy_audience_v2_interaction_event e on e.customer_id=candidate.customerId and e.occurred_at>=date_sub(current_date,interval 1 day) group by candidate.customerId
select candidate.customerId, cast(substring_index(group_concat(e.session_id order by e.occurred_at desc,e.id desc),',',1) as unsigned) sessionId, max(e.occurred_at) lastInteractionAt,count(e.id) interactionCount, sum(case when e.event_type='COMMENT' then 1 else 0 end) commentCount, case when sum(case when e.event_type='COMMENT' then 1 else 0 end)>0 then 'COMMENT' else 'VIEWER' end interactionType, case when sum(case when e.source_type='PLUGIN_REALTIME' then 1 else 0 end)>0 then 'PLUGIN' else 'MANUAL' end sourceType from ( select c.id customerId from dy_audience_v2_customer c
order by c.updated_at desc,c.id desc limit #{offset},#{limit} ) candidate join dy_audience_v2_interaction_event e on e.customer_id=candidate.customerId and e.occurred_at>=date_sub(current_date,interval 1 day) group by candidate.customerId
select c.id customerId, cast(substring_index(group_concat(e.session_id order by e.occurred_at desc,e.id desc),',',1) as unsigned) sessionId, max(e.occurred_at) lastInteractionAt,count(e.id) interactionCount, sum(case when e.event_type='COMMENT' then 1 else 0 end) commentCount, case when sum(case when e.event_type='COMMENT' then 1 else 0 end)>0 then 'COMMENT' else 'VIEWER' end interactionType, case when sum(case when e.source_type='PLUGIN_REALTIME' then 1 else 0 end)>0 then 'PLUGIN' else 'MANUAL' end sourceType from dy_audience_v2_customer c join dy_audience_v2_interaction_event e on e.customer_id=c.id
group by c.id order by lastInteractionAt desc,c.id desc limit #{offset},#{limit}
) page join dy_audience_v2_customer c on c.id=page.customerId left join dy_audience_v2_live_session s on s.id=page.sessionId left join sys_user ou on ou.user_id=c.owner_user_id order by page.lastInteractionAt desc,page.customerId desc

select /*+ MAX_EXECUTION_TIME(5000) */
  (select count(distinct pt.id) from dy_audience_v2_followup_task pt join dy_audience_v2_opportunity po on po.id=pt.opportunity_id where pt.status in ('PENDING','IN_PROGRESS') and pt.task_date=cast(convert_tz(now(),'+00:00','+08:00') as date) and po.session_id=#{sessionId}
    and exists(select 1 from dy_audience_v2_interaction_event tie where tie.customer_id=po.customer_id and tie.event_type=#{interactionType}and tie.session_id=#{sessionId}and tie.occurred_at>=concat(#{beginDate},' 00:00:00')and tie.occurred_at<date_add(#{endDate},interval 1 day))) today,
  (select count(distinct ot.id) from dy_audience_v2_followup_task ot join dy_audience_v2_opportunity oo on oo.id=ot.opportunity_id where ot.status in ('PENDING','IN_PROGRESS') and ot.task_date<cast(convert_tz(now(),'+00:00','+08:00') as date) and oo.session_id=#{sessionId}
    and exists(select 1 from dy_audience_v2_interaction_event tie where tie.customer_id=oo.customer_id and tie.event_type=#{interactionType}and tie.session_id=#{sessionId}and tie.occurred_at>=concat(#{beginDate},' 00:00:00')and tie.occurred_at<date_add(#{endDate},interval 1 day))) overdue,
  (select count(distinct cc.id) from dy_audience_v2_customer cc where cc.consult_stage='CONSULTING' and exists(select 1 from dy_audience_v2_interaction_event cie where cie.customer_id=cc.id and cie.session_id=#{sessionId}and cie.event_type=#{interactionType}and cie.occurred_at>=concat(#{beginDate},' 00:00:00')and cie.occurred_at<date_add(#{endDate},interval 1 day))) consulting,
  (select count(distinct ol.id) from dy_audience_v2_order_link ol join dy_audience_v2_opportunity op on op.id=ol.opportunity_id where ol.order_status in ('ORDERED_PENDING_NO','ENTERED_PENDING_SYNC') and op.session_id=#{sessionId}
    and exists(select 1 from dy_audience_v2_interaction_event tie where tie.customer_id=op.customer_id and tie.event_type=#{interactionType}and tie.session_id=#{sessionId}and tie.occurred_at>=concat(#{beginDate},' 00:00:00')and tie.occurred_at<date_add(#{endDate},interval 1 day))) orderPending,
  (select count(distinct ft.id) from dy_audience_v2_followup_task ft join dy_audience_v2_opportunity fo on fo.id=ft.opportunity_id where ft.task_type='PHONE_SERVICE' and ft.status not in ('DONE','RELEASED') and fo.session_id=#{sessionId}
    and exists(select 1 from dy_audience_v2_interaction_event tie where tie.customer_id=fo.customer_id and tie.event_type=#{interactionType}and tie.session_id=#{sessionId}and tie.occurred_at>=concat(#{beginDate},' 00:00:00')and tie.occurred_at<date_add(#{endDate},interval 1 day))) phoneHandoff
